// Runtime configuration generated by Terraform (config.json): no per-environment build.
import { DEMO } from './mock/enabled';

export interface Config {
  env: string;
  authority: string;
  clientId: string;
  authDomain: string;
}

let config: Config | null = null;

export async function loadConfig(): Promise<Config> {
  // Demo data (npm run dev:mock, development only): no deployment to read it from.
  if (DEMO) {
    config ??= { env: 'demo', authority: 'https://example.invalid', clientId: 'demo', authDomain: 'example.invalid' };
    return config;
  }
  if (!config) {
    const res = await fetch('/config.json', { cache: 'no-store' });
    if (!res.ok) throw new Error(`config.json: HTTP ${res.status}`);
    config = (await res.json()) as Config;
  }
  return config;
}

export function getConfig(): Config {
  if (!config) throw new Error('configuration not loaded');
  return config;
}
